function cashInPairs(s: string, abPoints: number, baPoints: number): number {
  const memo = new Map<string, number>();
  const go = (t: string): number => {
    if (memo.has(t)) return memo.get(t)!;
    let best = 0;
    for (let i = 0; i + 1 < t.length; i++) {
      const pair = t[i] + t[i + 1];
      const pts = pair === "ab" ? abPoints : pair === "ba" ? baPoints : -1;
      if (pts >= 0) best = Math.max(best, pts + go(t.slice(0, i) + t.slice(i + 2)));
    }
    memo.set(t, best);
    return best;
  };
  return go(s);
}

