function cashInPairs(s: string, abPoints: number, baPoints: number): number {
  const strip = (chars: string[], a: string, b: string, pts: number): [string[], number] => {
    const stack: string[] = [];
    let score = 0;
    for (const ch of chars) {
      if (ch === b && stack.length > 0 && stack[stack.length - 1] === a) {
        stack.pop();
        score += pts;
      } else stack.push(ch);
    }
    return [stack, score];
  };
  const abFirst = abPoints >= baPoints;
  const [rest, s1] = abFirst ? strip([...s], "a", "b", abPoints) : strip([...s], "b", "a", baPoints);
  const [, s2] = abFirst ? strip(rest, "b", "a", baPoints) : strip(rest, "a", "b", abPoints);
  return s1 + s2;
}

